[ExtensionOf(classStr(ReqCalc))]
internal final class AVARUMReqCalcCls_Extension
{
}

Method.Source:
protected ReqTrans initTransFromInventTrans
(
    ReqTrans _reqTrans,
    ReqSetup _setup,
    ReqSetupDim _setupDim,
    InventTrans _inventTrans,
    InventTransOrigin _inventTransOrigin
)
{
    _reqTrans = next initTransFromInventTrans(_reqTrans,_setup,_setupDim,_inventTrans,_inventTransOrigin);

    if (_reqTrans.RefType == ReqRefType::Production)
    {
        _reqTrans.AVARUMSalesRefTransId = ProdTable::find(_reqTrans.RefId).AVARUMSalesRefTransId;
    }

    return _reqTrans;
}
